css:
.stage {
  padding: 32px;
  font-family: system-ui, sans-serif;
}

.card {
  position: relative;
  width: 280px;
  height: 190px;
  margin: 0;
  overflow: hidden;
  border-radius: 12px;
}

.photo {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 400ms ease;
}

.caption {
  position: absolute;
  right: 0;
  bottom: 0;
  left: 0;
  padding: 12px 16px;
  background-color: rgb(0 0 0 / 0.65);
  color: #ffffff;
  transform: translateY(100%);
  transition: transform 250ms ease-out;
}

.card:hover .photo,
.card:focus-within .photo {
  transform: scale(1.06);
}

.card:hover .caption,
.card:focus-within .caption {
  transform: translateY(0);
}
